<?php require_once __DIR__.'/includes/permissions.php'; require_permission('records.view'); $pdo=db();$u=current_user();$error='';$services=active_services();$staff=$pdo->query('SELECT id,full_name,staff_id FROM users WHERE status="Active" ORDER BY full_name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=post('action');try{if($a==='save' && can('records.create')){$rid=(int)post('resident_id');$sid=(int)post('service_id');$type=trim((string)post('record_type'));$date=(string)post('record_date');$assigned=post('assigned_staff_id')!==''?(int)post('assigned_staff_id'):null;$diag=trim((string)post('diagnosis_summary'));$notes=trim((string)post('notes'));if(!$rid||!$sid||!$type||!$date)throw new Exception('Resident, service, record type and date are required.');if($u['role_name']!=='System Administrator'){$assigned=$u['id'];if($u['service_id'] && $sid!=(int)$u['service_id'])throw new Exception('Your role is restricted to your assigned service.');}$q=$pdo->prepare('INSERT INTO health_records(resident_id,service_id,record_type,record_date,assigned_staff_id,diagnosis_summary,notes,created_by) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$rid,$sid,$type,$date,$assigned,$diag,$notes,$u['id']]);audit('CREATE','health_records',(int)$pdo->lastInsertId(),'Health record created');flash('success','Health record saved.');redirect(BASE_URL.'/records.php');}elseif($a==='archive' && can('records.delete')){$id=(int)post('id');$q=$pdo->prepare('SELECT assigned_staff_id FROM health_records WHERE id=?');$q->execute([$id]);$r=$q->fetch();if($u['role_name']!=='System Administrator' && (!$r || (int)$r['assigned_staff_id']!==(int)$u['id']))throw new Exception('You can only archive your assigned records.');$pdo->prepare('UPDATE health_records SET status=IF(status="Active","Archived","Active") WHERE id=?')->execute([$id]);audit('ARCHIVE','health_records',$id,'Record archive status changed');flash('success','Record status updated.');redirect(BASE_URL.'/records.php');}}catch(Throwable $e){$error=$e->getMessage();}}
$where=['hr.status="Active"'];$params=[];$search=trim((string)get('search',''));$sid=(int)get('service',0);$type=trim((string)get('type',''));if($search){$where[]='(r.patient_id LIKE ? OR r.first_name LIKE ? OR r.last_name LIKE ?)';$x="%$search%";array_push($params,$x,$x,$x);}if($sid){$where[]='hr.service_id=?';$params[]=$sid;}if($type){$where[]='hr.record_type=?';$params[]=$type;}if($u['role_name']!=='System Administrator'){$where[]='hr.assigned_staff_id=?';$params[]=$u['id'];} $q=$pdo->prepare('SELECT hr.*,r.patient_id,r.first_name,r.last_name,s.name service_name,us.full_name staff_name FROM health_records hr JOIN residents r ON r.id=hr.resident_id JOIN services s ON s.id=hr.service_id LEFT JOIN users us ON us.id=hr.assigned_staff_id WHERE '.implode(' AND ',$where).' ORDER BY hr.record_date DESC,hr.id DESC');$q->execute($params);$rows=$q->fetchAll();$residents=$pdo->query('SELECT id,patient_id,first_name,last_name FROM residents WHERE status="Active" ORDER BY last_name,first_name')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Health Records</h1><p>Service-scoped patient records with server-side access restrictions.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel mb-4"><?php if(can('records.create')):?><div class="panel-head"><h5>Add Health Record</h5></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="save"><div class="col-md-4"><label>Patient *</label><select name="resident_id" class="form-select" required><option value="">Select patient</option><?php foreach($residents as $r):?><option value="<?=$r['id']?>"><?=e($r['patient_id'].' — '.$r['last_name'].', '.$r['first_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Service *</label><select name="service_id" class="form-select" required><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=($u['service_id']==$s['id'])?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Record Type *</label><select name="record_type" class="form-select" required><?php foreach(['Consultation','Dental Consultation','Laboratory Test','Pharmacy','ABTC Visit','Mental Health Consultation','Immunization','Maternal Care','Family Planning','Nutrition','TB/DOTS','Disease Surveillance'] as $x):?><option><?=$x?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Date *</label><input type="date" name="record_date" value="<?=date('Y-m-d')?>" class="form-control" required></div><?php if($u['role_name']==='System Administrator'):?><div class="col-md-4"><label>Assigned Staff</label><select name="assigned_staff_id" class="form-select"><option value="">Unassigned</option><?php foreach($staff as $x):?><option value="<?=$x['id']?>"><?=e($x['full_name'].' ('.$x['staff_id'].')')?></option><?php endforeach;?></select></div><?php endif;?><div class="col-md-4"><label>Diagnosis / Summary</label><textarea name="diagnosis_summary" class="form-control" rows="2"></textarea></div><div class="col-md-4"><label>Notes</label><textarea name="notes" class="form-control" rows="2"></textarea></div><div class="col-12"><button class="btn btn-primary">Save Record</button></div></form><?php endif;?></div><div class="panel"><div class="panel-head"><h5>Record List</h5><input class="form-control table-search" placeholder="Search table..." data-table-search="recordsTable"></div><form class="row g-2 mb-3" method="get"><div class="col-md-5"><input name="search" value="<?=e($search)?>" class="form-control" placeholder="Patient ID or name"></div><div class="col-md-4"><select name="service" class="form-select"><option value="">All services</option><?php foreach($services as $s):?><option value="<?=$s['id']?>" <?=$sid===$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input name="type" value="<?=e($type)?>" class="form-control" placeholder="Record type"></div><div class="col-md-1"><button class="btn btn-outline-primary">Go</button></div></form><div class="table-responsive"><table class="table align-middle" id="recordsTable"><thead><tr><th>Patient</th><th>Service</th><th>Type</th><th>Date</th><th>Assigned</th><th>Summary</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['patient_id'])?></strong><br><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['service_name'])?></td><td><?=e($r['record_type'])?></td><td><?=e($r['record_date'])?></td><td><?=e($r['staff_name']??'Unassigned')?></td><td><?=e(mb_strimwidth((string)$r['diagnosis_summary'],0,70,'…'))?></td><td><?php if(can('records.delete')):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary">Archive</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
